import React, { useState, useEffect } from 'react';
import QuestionItem from '../components/QuestionItem';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';

const generateId = () => Date.now() + Math.random();

const BuilderPage = () => {
    const [questions, setQuestions] = useState(() => {
        const saved = localStorage.getItem('questions');
        return saved ? JSON.parse(saved) : [];
    });

    useEffect(() => {
        localStorage.setItem('questions', JSON.stringify(questions));
    }, [questions]);

    // Add Parent Question
    const addParentQuestion = () => {
        const newQuestion = {
            id: generateId(),
            text: '',
            type: 'Short Answer',
            answer: '',
            userAnswer: '',
            children: [],
        };

        setQuestions([...questions, newQuestion]);
    };

    // Update Question
    const updateQuestion = (id, updatedData, items = questions) => {
        return items.map((item) => {
            if (item.id === id) {
                return { ...item, ...updatedData };
            }

            return {
                ...item,
                children: updateQuestion(id, updatedData, item.children),
            };
        });
    };

    const handleUpdate = (id, data) => {
        setQuestions((prev) => updateQuestion(id, data, prev));
    };

    // Delete Question
    const deleteQuestion = (id, items = questions) => {
        return items
            .filter((item) => item.id !== id)
            .map((item) => ({
                ...item,
                children: deleteQuestion(id, item.children),
            }));
    };

    const handleDelete = (id) => {
        setQuestions((prev) => deleteQuestion(id, prev));
    };

    // Add Child Question
    const addChildQuestion = (parentId, items = questions) => {
        return items.map((item) => {
            if (item.id === parentId) {
                const child = {
                    id: generateId(),
                    text: '',
                    type: 'Short Answer',
                    answer: '',
                    userAnswer: '',
                    children: [],
                };

                return {
                    ...item,
                    children: [...item.children, child],
                };
            }

            return {
                ...item,
                children: addChildQuestion(parentId, item.children),
            };
        });
    };

    const handleAddChild = (parentId) => {
        setQuestions((prev) => addChildQuestion(parentId, prev));
    };

    return (
        <div className="bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 min-h-screen pt-20">

            <Sidebar />

            <div className="flex-1 p-8 overflow-auto">

                <div className="bg-white/95 backdrop-blur-md shadow-xl rounded-3xl p-8">

                    <div className="flex justify-between items-center mb-8">

                        <div>

                            <h1 className="text-4xl font-bold text-gray-800">
                                Form Builder
                            </h1>

                            <p className="text-gray-500 mt-1">
                                Create and manage nested questions
                            </p>

                        </div>

                        <button
                            onClick={addParentQuestion}
                            className="
              bg-gradient-to-r
              from-blue-500
              to-indigo-500
              hover:from-indigo-500
              hover:to-blue-500
              text-white
              px-6 py-3
              rounded-2xl
              shadow-lg
              transition-all
              duration-300
            "
                        >
                            + Add Question
                        </button>

                    </div>

                    {questions.length === 0 ? (

                        <div className="text-center py-20">

                            <h2 className="text-2xl font-semibold text-gray-600 mb-2">
                                No Questions Yet
                            </h2>

                            <p className="text-gray-400">
                                Start building your form by adding a question.
                            </p>

                        </div>

                    ) : (

                        questions.map((question, index) => (
                            <QuestionItem
                                key={question.id}
                                question={question}
                                numbering={`Q${index + 1}`}
                                onUpdate={handleUpdate}
                                onDelete={handleDelete}
                                onAddChild={handleAddChild}
                            />
                        ))

                    )}

                </div>

            </div>

        </div>
    );
};

export default BuilderPage;
